def seed_wards(apps, schema_editor):
    from core.lga_data import KANO_LGAS

    Ward = apps.get_model("core", "Ward")
    PollingUnit = apps.get_model("core", "PollingUnit")
    Ward.objects.bulk_create(
        [
            Ward(lga=lga, ward_index=index, name=name, sort_order=index)
            for lga, _, wards in KANO_LGAS
            for index, name in enumerate(wards)
        ],
        batch_size=500,
    )
    ward_ids = {
        (ward.lga, ward.ward_index): ward.pk
        for ward in Ward.objects.all()
    }
    units = []
    for unit in PollingUnit.objects.all().iterator():
        ward_id = ward_ids.get((unit.lga, unit.ward_index))
        if ward_id is not None:
            unit.ward_record_id = ward_id
            units.append(unit)
    if units:
        PollingUnit.objects.bulk_update(units, ["ward_record"], batch_size=500)


